export const TOTAL_STEPS2 = PLAN2.reduce((n, d) => n + d.steps.length, 0);

/** Every step, flattened with its day — mirrors store.ts ALL_STEPS for plan 2. */
export const ALL_STEPS2: { day: number; date: string; dayTitle: string; step: Step2 }[] =
  PLAN2.flatMap((d) => d.steps.map((step) => ({ day: d.day, date: d.date, dayTitle: d.title, step })));

/** Step counts by how they run — for the Testing page's summary. */
export const PLAN2_BY_METHOD: Record<Method, number> = ALL_STEPS2.reduce(
  (acc, s) => { acc[s.step.method] += 1; return acc; },
  { api: 0, code: 0, browser: 0 } as Record<Method, number>,
);
